+	}
+	manifest, err := loadWorkspaceManifest(opts.Env, workspaceName)
+	if err != nil {
+		return err
+	}
+	var results []workspaceQueryResult
+	for _, repo := range manifest.Repos {
+		freshness := workspaceRepoFreshnessForRepo(cmd.Context(), opts, repo)
