			return nil, nil, err
		}
		relations, err := findSemanticRelationsForSymbolsInSQLite(storePath, symbols, limit*4)
		return symbols, relations, err
	}
	snapshotPath, err := validateSemanticSnapshotPath(source.SnapshotPath)
	if err != nil {
